package exercise
import "sync"
type cacheState struct { mu sync.Mutex; values map[string]int }
type Cache struct { state *cacheState }
func NewCache() Cache { return Cache{state: &cacheState{values: make(map[string]int)}} }
func (c Cache) Add(key string, delta int) int {
 c.state.mu.Lock(); defer c.state.mu.Unlock()
 c.state.values[key] += delta
 return c.state.values[key]
}
func (c Cache) Get(key string) (int, bool) {
 c.state.mu.Lock(); defer c.state.mu.Unlock()
 value, ok := c.state.values[key]; return value, ok
}
```

原题知识说明：
审查方法接收者和结构体所有复制路径，结合race报告证明map共享而锁被复制。不同调用锁住各自副本，不能保护同一底层map。暂停问题版本的扩流，必要时回到已批准稳定制品；交开发改为稳定共享锁与指针所有权并清理其他复制点。验收并发读写、复制路径静态检查与race覆盖，不能只在报错函数额外增加一把局部锁。

