import ("testing"; "sync"; "fmt")
func TestAliases(t *testing.T) {
 c := NewCache(); alias := c
 if c.Add("before", 9) != 9 { t.Fatal("initial") }
 if v, ok := alias.Get("before"); !ok || v != 9 { t.Fatal("copy no longer aliases shared cache") }
 if _, ok := c.Get("missing"); ok { t.Fatal("missing versus zero") }
 if c.Add("zero", 0) != 0 { t.Fatal("zero") }
 if v, ok := alias.Get("zero"); !ok || v != 0 { t.Fatal("zero value presence") }
 var wg sync.WaitGroup
 for worker := 0; worker < 8; worker++ {
  handle := c; if worker%2 == 1 { handle = alias }
  wg.Add(1); go func(n int, h Cache) { defer wg.Done(); for i:=0;i<300;i++ {
   h.Add("total", 1); h.Add(fmt.Sprintf("worker-%d",n), 1); h.Get("total")
  } }(worker,handle)
 }
 wg.Wait()
 if v, ok := alias.Get("total"); !ok || v != 2400 { t.Fatalf("lost update: %d %v",v,ok) }
 for i:=0;i<8;i++ { if v,_:=c.Get(fmt.Sprintf("worker-%d",i)); v!=300 {t.Fatal("worker total",i,v)} }
