package exercise
import ("context"; "errors")
func Start(ctx context.Context, input <-chan int, handle func(int) error) (<-chan error, error) {
 if ctx==nil || input==nil || handle==nil { return nil, errors.New("worker dependencies must be non-nil") }
 result:=make(chan error,1)
 go func() {
  defer close(result)
  for {
   select {
   case <-ctx.Done(): result<-ctx.Err();return
   case value,ok:=<-input:
    if !ok {result<-nil;return}
    if err:=handle(value);err!=nil {result<-err;return}
   }
  }
 }()
 return result,nil
}
```

原题知识说明：
核对构造路径、变量遮蔽和赋值顺序，结合goroutine栈确认select中的输入通道值。nil channel通信永远阻塞，在select里相当于禁用该分支，所以只有取消分支可走。停止接受新任务并排出未处理清单，开发在启动前校验依赖非nil并消除错误遮蔽。验收正常输入可消费、缺依赖启动失败及取消可退出，不能用default忙轮询掩盖nil输入。

