package exercise
import ("testing"; "context"; "errors"; "time"; "reflect")
func wait(t *testing.T, result <-chan error) error {
 t.Helper();select {case err,ok:=<-result:if !ok {t.Fatal("closed without result")};
 select {case _,ok=<-result:if ok{t.Fatal("extra result")};case <-time.After(time.Second):t.Fatal("result never closed")};return err
 case <-time.After(time.Second):t.Fatal("worker did not terminate");return nil}
}
func TestStartup(t *testing.T) {
 input:=make(chan int)
 for _,params:=range []struct{ctx context.Context;in <-chan int;fn func(int)error}{
  {context.Background(),nil,func(int)error{return nil}},
  {nil,input,func(int)error{return nil}},
  {context.Background(),input,nil},
 } {done,err:=Start(params.ctx,params.in,params.fn);if err==nil||done!=nil {t.Fatal("invalid dependencies started a worker")}}
}
func TestConfiguredChannelAndClose(t *testing.T) {
 input:=make(chan int,3);input<-0;input<-7;input<-19;close(input)
 got:=[]int{};done,err:=Start(context.Background(),input,func(v int)error{got=append(got,v);return nil})
 if err!=nil {t.Fatal(err)};if err=wait(t,done);err!=nil{t.Fatal(err)}
 if !reflect.DeepEqual(got,[]int{0,7,19}){t.Fatal("wrong or shadowed input channel",got)}
}
func TestCancellation(t *testing.T) {
 ctx,cancel:=context.WithCancel(context.Background());defer cancel();input:=make(chan int,1)
 done,err:=Start(ctx,input,func(int)error{return nil});if err!=nil{t.Fatal(err)};cancel()
 if err=wait(t,done);!errors.Is(err,context.Canceled){t.Fatal("cancellation",err)}
 input<-42 // worker must not close caller-owned input
}
func TestHandlerError(t *testing.T) {
 input:=make(chan int,2);input<-3;input<-8;sentinel:=errors.New("write failed");calls:=0
 done,err:=Start(context.Background(),input,func(int)error{calls++;return sentinel});if err!=nil{t.Fatal(err)}
 if err=wait(t,done);!errors.Is(err,sentinel)||calls!=1{t.Fatal("lost handler failure",err,calls)}
 if <-input!=8{t.Fatal("consumed later input after failure")}
}
